INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.18, 3001, "フフ、全問正解よ！\nちゃんと勉強してるみたいで\n感心だわ♪", 10, 1, 7, 4, "vo_minigame_1012_result_1000", 8, 1, 10, 11300101);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.33, 3001, "すごいじゃない…全問正解よ！\nま、当然といや当然よね～\nだってあたしが\n教えてやってんだから♪", 10, 1, 8, 10, "vo_minigame_1012_result_1001", 7, 1, 10, 11300102);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 5.41, 3001, "全問正解！　パチパチパチ～♪\nこの難易度はもう完璧じゃない？\n次はもっと難しい問題に挑戦よ！\nあんたならできるって！", 10, 1, 8, 10, "vo_minigame_1012_result_1002", 1, 1, 10, 11300103);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 8.11, 3001, "へえ…難しい問題を選んだのに\n全問正解できてるじゃない！！\nちょっとあんたすごすぎだわ…！\nパーフェクトよパーフェクト！", 10, 1, 5, 10, "vo_minigame_1012_result_1003", 8, 1, 10, 11300104);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 1.31, 3001, "まる…まる…全部まる！\n難しい問題なのに全問正解よ…！\n驚いた…あんたいつの間に、\nこんなに勉強してたのよ！", 10, 1, 10, 0, "vo_minigame_1012_result_1004", 5, 1, 10, 11300105);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.93, 3001, "ここまで完璧に正解されちゃうと\nちょっと悔しいわね…！\nけど素直に褒めてやるわ！\nえらい、えらい、えら～い！", 10, 1, 9, 0, "vo_minigame_1012_result_1005", 8, 1, 10, 11300106);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.99, 3001, "すごい…あんたパーフェクトよ！\nこのままいけば次の試験、\n学年一位も夢じゃないかもね！\n楽しみだわ～♪", 10, 1, 5, 4, "vo_minigame_1012_result_1006", 8, 1, 10, 11300107);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 8.37, 3001, "満点よ！　フフ、もうあんたに\n教えることはなにもないわ…！\n逆にあたしがあんたに教わりたい\nくらいよ！　…ね、先生♪", 10, 1, 8, 4, "vo_minigame_1012_result_1007", 7, 1, 10, 11300108);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.32, 3001, "全・問・正・解！\n超難問揃いなのにすごいわね…！\nもしかしてだけど、\nあんたって天才！？", 10, 1, 7, 8, "vo_minigame_1012_result_1008", 5, 1, 10, 11300109);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.77, 3001, "お、かなりいい点数ね～！\nあたしも教えがいがあるわ♪\nさ、まだまだ勉強するわよ！", 7, 1, 7, 4, "vo_minigame_1012_result_1009", 1, 1, 9, 11300110);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.97, 3001, "うん、いい感じで点取れてるわ！\nこの調子で次は、\n満点を見せてほしいわね！", 7, 1, 8, 4, "vo_minigame_1012_result_1010", 7, 1, 9, 11300111);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.47, 3001, "あ～惜しい！\nもうちょっとで満点じゃない！\n次はパーフェクトいけるわ！\n頑張りましょ！", 7, 1, 5, 0, "vo_minigame_1012_result_1011", 1, 1, 9, 11300112);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.32, 3001, "すごい、かなりできてるわよ！\n難しい問題なのにやるじゃない！\nあとは目指せ、満点ね！", 7, 1, 8, 4, "vo_minigame_1012_result_1012", 7, 1, 9, 11300113);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 6.49, 3001, "うん、かなりいい感じよ！\nあんたには赤点の心配なんて\nまーったくなさそうね♪\nでも勉強はやめさせないけど！", 7, 1, 8, 10, "vo_minigame_1012_result_1013", 7, 1, 9, 11300114);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3.56, 3001, "あーあとちょっとで\n全問正解だったのに！\n難しい問題だけどあんたなら\n次は満点狙えるわ！", 7, 1, 5, 0, "vo_minigame_1012_result_1014", 1, 1, 9, 11300115);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.67, 3001, "うん、ほとんど正解よ！\nこんな難しい問題なのに、\nすごいじゃない！\nやっぱりあんた只者じゃないわ！", 7, 1, 8, 10, "vo_minigame_1012_result_1015", 1, 1, 9, 11300116);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.85, 3001, "着実に成長してるって感じね？\nあんたならこの難問でも、\nいつか満点取れちゃうかも…！", 7, 1, 7, 10, "vo_minigame_1012_result_1016", 1, 1, 9, 11300117);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.88, 3001, "うわー惜しいわね！\nもうちょっとで満点よ？\nま、あたしでも悩む難問だから、\nこの点数は胸を張っていいわ！", 7, 1, 5, 0, "vo_minigame_1012_result_1017", 1, 1, 9, 11300118);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.12, 3001, "正解率は半分くらいか～\n悪くはないんだけど、あんたなら\nこんなもんじゃないでしょ？", 4, 1, 3, 0, "vo_minigame_1012_result_1018", 1, 1, 6, 11300119);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.34, 3001, "んーはっきり言っちゃうと\n中途半端な点数ね…\nまあいいわ！こっからガンガン\n点数上げていくわよ！", 4, 1, 9, 0, "vo_minigame_1012_result_1019", 1, 1, 6, 11300120);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.15, 3001, "う～ん、正直物足りない点数ね！\nあんたには期待してんだから、\nもっと頑張んなさい！", 4, 1, 3, 0, "vo_minigame_1012_result_1020", 1, 1, 6, 11300121);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.3, 3001, "半分くらいの正解率か\n難しい問題だから仕方ないわね…\nでもあんたはもっとできる！\nだってあたしがついてんのよ！", 4, 1, 9, 0, "vo_minigame_1012_result_1021", 1, 1, 6, 11300122);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.55, 3001, "うん、そこそこできんじゃない！\n頑張って勉強して\nさらに上を目指しましょ！", 4, 1, 8, 0, "vo_minigame_1012_result_1022", 1, 1, 6, 11300123);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.19, 3001, "難問なのにこの正解率は\nよくやってる方よね！\nでもこんなところで\n満足してんじゃないわよ！？", 4, 1, 1, 0, "vo_minigame_1012_result_1023", 7, 1, 6, 11300124);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.43, 3001, "難問なのに半分くらい正解\nできてんじゃない♪\nこの調子でもっと学力\n上げていきましょ！", 4, 1, 7, 0, "vo_minigame_1012_result_1024", 1, 1, 6, 11300125);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "よし、平均点ってとこね！\nちゃんと勉強してるみたいで\n安心したわ～♪", 4, 1, 1, 0, "vo_minigame_1012_result_1025", 1, 1, 6, 11300126);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.72, 3001, "難問揃いでこの正解率は\n大したもんよ！\nま、もっといい点取りたいんなら\n勉強、付き合ったげるわ！", 4, 1, 8, 0, "vo_minigame_1012_result_1026", 7, 1, 6, 11300127);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.5, 3001, "なるほど…\nこれは教えがいがあるわね\nビシバシ鍛えてやるから\n覚悟しなさい！", 1, 1, 3, 1, "vo_minigame_1012_result_1027", 2, 1, 3, 11300128);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.25, 3001, "ちょっとあんた、\n全然できてないじゃない！\n…まさかこれが本気だなんて\n言わないわよね～？", 1, 1, 4, 1, "vo_minigame_1012_result_1028", 2, 1, 3, 11300129);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.62, 3001, "うーん……適当に答えても\nこれくらい正解できるわよ？\nちょっと本腰入れて\n教えないとね……！", 1, 1, 3, 0, "vo_minigame_1012_result_1029", 2, 1, 3, 11300130);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.5, 3001, "…ま、まあこの問題は\nあんたには難しすぎたのかもね\nちょっとずつでいいから、\nレベルアップしていきましょ！", 1, 1, 9, 0, "vo_minigame_1012_result_1030", 1, 1, 3, 11300131);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.01, 3001, "んー結構ミスっちゃってるわね…\nこのまま続けるのもいいけど、\n簡単な問題からやり直すのも\nありかもよ～？", 1, 1, 3, 9, "vo_minigame_1012_result_1031", 3, 1, 3, 11300132);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.01, 3001, "あらら、あんたにはちょっと\n難しすぎたかしら…？\nもう一回やり直しましょうか！", 1, 1, 9, 9, "vo_minigame_1012_result_1032", 9, 1, 3, 11300133);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.01, 3001, "うーん、残念な結果ね…\n超難問だから仕方ないけど\n無理せず簡単な問題から挑戦\nしてもいいかもよ？", 1, 1, 3, 6, "vo_minigame_1012_result_1033", 3, 1, 3, 11300134);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.97, 3001, "正解率はかなり悪いわね…\nまあ難しい問題だもんね…！\nそのチャレンジ精神は買うわ！", 1, 1, 3, 0, "vo_minigame_1012_result_1034", 9, 1, 3, 11300135);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.1, 3001, "なんとか０点は免れたわね…\n難問揃いだけど、\nもっと頑張っていきましょ！", 1, 1, 3, 0, "vo_minigame_1012_result_1035", 1, 1, 3, 11300136);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.31, 3001, "…あんたさ、０点なんて\n逆に取るの難しいわよ！？\nまさか狙ったわけじゃ\nないでしょーね～！？", 0, 1, 6, 1, "vo_minigame_1012_result_1036", 2, 1, 0, 11300137);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.1, 3001, "０点って…\nあんたふざけてんの！？\nちゃんとやらないなら\n電撃魔法くらわせるわよ！？", 0, 1, 2, 1, "vo_minigame_1012_result_1037", 2, 1, 0, 11300138);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.23, 3001, "もしかしたらあんたは\n勉強向いてないのかもね…\n…勉強だけがすべてじゃないわ\n違うとこで頑張りましょ！", 0, 1, 9, 9, "vo_minigame_1012_result_1038", 3, 1, 0, 11300139);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.38, 3001, "怒んないから正直に言って？\n…ふざけて答えたでしょ？\nほら、正直に\n言・い・な・さ・い？", 0, 1, 3, 0, "vo_minigame_1012_result_1039", 2, 1, 0, 11300140);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3.58, 3001, "あんたの点数は～～…\n…はい！　０てーん！！\n…って、ふざけんなーー！！！", 0, 1, 8, 0, "vo_minigame_1012_result_1040", 2, 1, 0, 11300141);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.02, 3001, "０点ってどういうこと！？\nいやあんた、逆にすごいわよ！？\n目つぶってやったとしても\n１点は取れるから！", 0, 1, 4, 1, "vo_minigame_1012_result_1041", 2, 1, 0, 11300142);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.53, 3001, "あちゃー……残念だけど０点よ\nちょっと難しすぎたかもねー…\n…ま、こんなこともあるわ！\n気を落とさなくていいわよ！", 0, 1, 9, 9, "vo_minigame_1012_result_1042", 1, 1, 0, 11300143);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.4, 3001, "かなりの難問とはいえ、\n０点はちょっと寂しいわね…\nでもま、逆に考えるのよ！\nあんたには伸びしろしかないわ！", 0, 1, 3, 9, "vo_minigame_1012_result_1043", 1, 1, 0, 11300144);
