INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.74, 3001, "はい、よくできました！\n基礎はもう完璧ね！\n次はもっと難しい問題にも\nチャレンジしちゃいなさいよ！", 20, 1, 7, 10, "vo_minigame_1012_result_1045", 1, 2, -1, 12300101);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.85, 3001, "なによあんた、走り出したペンが\n止まらないって感じ？\nったくシンプルにすごいじゃない\n花丸あげるわ！", 20, 1, 1, 0, "vo_minigame_1012_result_1046", 9, 2, -1, 12300102);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "すごい点数ね…！\nあんた勉強してないとか言って\nホントはめちゃくちゃやってる\nパターンのやつね！？", 20, 1, 5, 8, "vo_minigame_1012_result_1047", 5, 2, -1, 12300103);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.86, 3001, "勉強の成果、\nちゃんとでてんじゃない！\nあたしもあんたの先生として、\n鼻が高いわ～♪", 20, 1, 8, 4, "vo_minigame_1012_result_1048", 7, 2, -1, 12300104);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.02, 3001, "オッケー！　もう十分よ！\nこれ以上でき過ぎちゃったら、\nあたしが教える必要なくなるわ！", 20, 1, 5, 9, "vo_minigame_1012_result_1049", 3, 2, -1, 12300105);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.46, 3001, "難しい問題を選んだつもりなのに\nすごい正解数ね…！\nでもまだ上がある…\n次は最難関に挑戦よ！", 20, 1, 5, 0, "vo_minigame_1012_result_1050", 1, 2, -1, 12300106);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 6.85, 3001, "すごいすごいとは思ってたけど、\nあんた勉強も完璧なの…？\nそりゃみんなあんたに惚れ…\nや、な、なんでもない！！", 20, 1, 5, 7, "vo_minigame_1012_result_1051", 4, 2, -1, 12300107);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.79, 3001, "この問題、あたしでも悩む\n超難問なのに…\nふふっ、もう褒めるしかないわ！\n大変よくできました！", 20, 1, 5, 0, "vo_minigame_1012_result_1052", 9, 2, -1, 12300108);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.01, 3001, "別に顔赤くなんてなってない！\n頭がいい人が好きとか…\nかっこいいとか…\n…思ってないからね！", 20, 1, 4, 7, "vo_minigame_1012_result_1053", 4, 2, -1, 12300109);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？", 20, 1, 5, 0, "vo_minigame_1012_result_1054", 5, 2, -1, 12300110);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？", 20, 1, 5, 0, "vo_minigame_1012_result_1054", 5, 2, -1, 12300112);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？", 20, 1, 5, 0, "vo_minigame_1012_result_1054", 5, 2, -1, 12300114);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.0, 3001, "おお～かなり正解できてるわね！\nこの調子でもっとすごい点\n目指しちゃうわよ！", 15, 1, 5, 10, "vo_minigame_1012_result_1056", 7, 2, 19, 12300116);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "うん、バッチリいい感じよ！\nちゃんと勉強してるみたいで\n関心関心♪", 15, 1, 8, 10, "vo_minigame_1012_result_1057", 8, 2, 19, 12300117);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.01, 3001, "え、こんなにいい点取れたのに\nまだ満足してないの？\nなによその向上心…\nいいじゃない！", 15, 1, 5, 0, "vo_minigame_1012_result_1058", 8, 2, 19, 12300118);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.83, 3001, "スピードも正解数もいい感じよ！\nねえねえ、この調子で\nてっぺん目指しちゃう？", 15, 1, 8, 10, "vo_minigame_1012_result_1059", 7, 2, 19, 12300119);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "この難易度でも\nスラスラ答えちゃうなんて…\nあんたって\nほんとすごいやつよね…！", 15, 1, 10, 0, "vo_minigame_1012_result_1060", 10, 2, 19, 12300120);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3.66, 3001, "これだけ正解できたら\n勉強も楽しいわよね♪\nさ、まだまだ続けるわよ～！", 15, 1, 8, 4, "vo_minigame_1012_result_1061", 7, 2, 19, 12300121);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.28, 3001, "あんた、この成績\nまぐれじゃないわよね…！\nこれだけできたら\n大したもんだわ！", 15, 1, 5, 0, "vo_minigame_1012_result_1062", 8, 2, 19, 12300122);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.7, 3001, "すごい！　とってもいい成績よ！\nこの難問も、あんたにかかりゃ\nイチコロってやつ？", 15, 1, 8, 0, "vo_minigame_1012_result_1063", 1, 2, 19, 12300123);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.98, 3001, "あんた…もしかして\nあたしより点数いいかも？\nあ、あたしもあんたを見習って\n勉強しないとね…！", 15, 1, 5, 9, "vo_minigame_1012_result_1064", 9, 2, 19, 12300124);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.51, 3001, "うん、なかなかいい点数よ！\nでもまだまだ頑張れるわよね？\nはい、次いきましょ！", 10, 1, 7, 0, "vo_minigame_1012_result_1067", 1, 2, 14, 12300131);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.16, 3001, "十分優秀な成績だけど\nあんたならもっとできる！\nさ、頑張って勉強するわよ！", 10, 1, 1, 0, "vo_minigame_1012_result_1068", 7, 2, 14, 12300132);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.07, 3001, "うん、いい感じね！\nこの調子で少しずつ、\n正解数を増やしてくわよ！", 10, 1, 8, 0, "vo_minigame_1012_result_1069", 7, 2, 14, 12300133);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3.51, 3001, "難問揃いなのに、\nけっこーいい感じじゃない！\nちゃんとできてるから\n自信もっていいわよ！", 10, 1, 8, 0, "vo_minigame_1012_result_1070", 1, 2, 14, 12300134);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "難しい問題でも基礎は大事よ！\nこの調子でどんどん\n点数上げていきましょう！", 10, 1, 1, 0, "vo_minigame_1012_result_1071", 1, 2, 14, 12300135);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.3, 3001, "10問以上取れてるわね！\nえ、まだ物足りない？\nフフ、じゃあもっと上\n目指しちゃう？", 10, 1, 1, 0, "vo_minigame_1012_result_1072", 7, 2, 14, 12300136);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.47, 3001, "うん、この難問でこの点数は\n十分すぎる出来よね！\nま、あんたならもっといい点\n目指しちゃうんだろうけど♪", 10, 1, 8, 0, "vo_minigame_1012_result_1073", 7, 2, 14, 12300137);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.68, 3001, "はいお疲れ～\nなかなか良い点数じゃない\n…あたしも勉強しないとね！", 10, 1, 8, 0, "vo_minigame_1012_result_1074", 9, 2, 14, 12300138);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.34, 3001, "おお～10問以上\n正解してんじゃない！\nあんたやっぱり\nただ者じゃないわね～", 10, 1, 5, 0, "vo_minigame_1012_result_1075", 1, 2, 14, 12300139);
