INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.24, 3001, "ふ～ん、まあまあの出来だわ\n悪くはないんだけど…あんたには\nもっともっと期待してるわ～", 5, 1, 1, 0, "vo_minigame_1012_result_1078", 7, 2, 9, 12300146);
