INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "まあまあな点数だけど、\n自分的に手ごたえはどう？\nダメだって思ってんなら、\nまだまだ伸びる余地ありね！", 5, 1, 1, 0, "vo_minigame_1012_result_1080", 1, 2, 9, 12300148);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.21, 3001, "うん、中々の出来ね！\nでもあんたはもっといい点\n取れるはずよ！\nもっと頑張りましょうか！", 5, 1, 8, 0, "vo_minigame_1012_result_1081", 1, 2, 9, 12300149);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.46, 3001, "ん～はっきり言って微妙ね！\nま、難しい問題だし、\n勉強すれば\n点数は上がっていくと思うわ！", 5, 1, 3, 0, "vo_minigame_1012_result_1082", 1, 2, 9, 12300150);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.94, 3001, "ん～…\n10点には届かなかったか～\n次は10点越え目指して\n頑張ってみない？", 5, 1, 3, 0, "vo_minigame_1012_result_1083", 1, 2, 9, 12300151);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.19, 3001, "はいお疲れ～\n点数的にはまあまあってとこね！\nま、超難問だし頑張ったわよ", 5, 1, 7, 0, "vo_minigame_1012_result_1084", 1, 2, 9, 12300152);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "うん、かなり難しい問題なのに\n最後までやり遂げたわね\n次はもっといい点目指してみる？", 5, 1, 1, 0, "vo_minigame_1012_result_1085", 1, 2, 9, 12300153);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.63, 3001, "ちょっとミスが多かったかもね～\nでも間違えた所は復習して\n次は正解するわよー！", 5, 1, 3, 0, "vo_minigame_1012_result_1086", 1, 2, 9, 12300154);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 5.53, 3001, "あら…あんまり良くない点数ね～\nどうしたの、調子でも悪かった？\n次はもっと頑張りましょうか", 1, 1, 3, 0, "vo_minigame_1012_result_1087", 1, 2, 4, 12300155);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "ん～…正解数は\n物足りないわね～\nもうちょっと勉強の時間\n増やしちゃおっか？", 1, 1, 3, 9, "vo_minigame_1012_result_1088", 3, 2, 4, 12300156);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.15, 3001, "ん～…あんたならもうちょと\nいい点取れんでしょ～？\nもっと頑張んなさいよ\n期待してやってんだからさ！", 1, 1, 3, 3, "vo_minigame_1012_result_1089", 1, 2, 4, 12300157);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.01, 3001, "ん～今のあんたには、\nこの問題は難しかったかしら…\n難易度下げてチャレンジするのも\nありかもね～？", 1, 1, 9, 9, "vo_minigame_1012_result_1090", 9, 2, 4, 12300158);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.37, 3001, "あんまり出来は良くないわね～\n難しい問題だししょうがないけど\n次はもっと頑張ってほしいわ！", 1, 1, 3, 0, "vo_minigame_1012_result_1091", 1, 2, 4, 12300159);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 1.44, 3001, "なるほど…\nちょっと苦手な問題が多かった？\nもう一度チャレンジ\nしてみましょうか～", 1, 1, 3, 0, "vo_minigame_1012_result_1092", 1, 2, 4, 12300160);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "んん～…問題が難しすぎた？\n無理に難しい問題続けるより、\n難易度下げた方が\n勉強の効率良いかもよ～？", 1, 1, 3, 0, "vo_minigame_1012_result_1093", 3, 2, 4, 12300161);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.91, 3001, "…あんまり点数取れなかったわね\nこれはあたしにも難しい問題だし\nそう落ち込まなくても大丈夫！\n次頑張りましょ！", 1, 1, 3, 3, "vo_minigame_1012_result_1094", 9, 2, 4, 12300162);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.61, 3001, "ごめん、ちょっと難しすぎた？\nもう一度チャレンジするも良し、\n難易度を下げるも良し、\nあんたがやる気なら付き合うわ！", 1, 1, 5, 0, "vo_minigame_1012_result_1095", 1, 2, 4, 12300163);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.63, 3001, "ちょっとあんた…\nやる気ないわよね～！？\n次こんな点数取ったら\n怒るわよ！", 0, 1, 4, 1, "vo_minigame_1012_result_1096", 2, 2, 0, 12300164);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.16, 3001, "はあ…自分で何点取ったか\n分かってるわよね～…？\n０点よ０点！　舐めてんの！？", 0, 1, 6, 1, "vo_minigame_1012_result_1097", 2, 2, 0, 12300165);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "うう～頭痛い…\nあんたのせいよ！\nなに０点って！\nはあ、このままじゃ赤点よ～…", 0, 1, 3, 6, "vo_minigame_1012_result_1098", 3, 2, 0, 12300166);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.75, 3001, "ねえ、あんた本気でやったの？\nまさか適当にやるわけないわよね\n…分かった、\nもう一回チャレンジするのよ！", 0, 1, 6, 0, "vo_minigame_1012_result_1099", 2, 2, 0, 12300167);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.64, 3001, "あ…あんた、０点よ０点…！\nあたしの教え方が悪かった…？\n…燃えてきたわ！\n絶対あんたの学力上げてやる！", 0, 1, 4, 1, "vo_minigame_1012_result_1100", 2, 2, 0, 12300168);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.73, 3001, "ちょっと待って採点ミスかも…\n…いや合ってるわね。はい０点\n…って０点！？\nふざけんなーー！", 0, 1, 8, 8, "vo_minigame_1012_result_1101", 4, 2, 0, 12300169);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.32, 3001, "あらら…０点よ\nま、難しい問題だしね…\n…つっても０点は無いわ！\n一問くらい正解しなさいよ！", 0, 1, 5, 1, "vo_minigame_1012_result_1102", 3, 2, 0, 12300170);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.37, 3001, "残念だけど０点よ\nま、まあ前向きにとらえるなら、\n今が底よ！　どん底！\nあとは上がってくだけね！", 0, 1, 3, 9, "vo_minigame_1012_result_1103", 9, 2, 0, 12300171);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.25, 3001, "…かなり出来が悪いわね\n一旦休憩しましょうか？\nリフレッシュして頭切り替えて\nもう一度頑張りましょう！", 0, 1, 9, 3, "vo_minigame_1012_result_1104", 1, 2, 0, 12300172);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (0, 0.0, 1001, "さ、勉強を始めるわよ", 0, 1, 7, 0, "vo_minigame_1012_gamestart_100", 7, 3, 0, 13100101);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (0, 0.0, 1001, "よし、勉強の成果を見てやるわ！", 0, 1, 1, 0, "vo_minigame_1012_gamestart_101", 1, 3, 0, 13100102);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (0, 1.82, 1001, "じゃあ試験するわよ。はい教科書閉じて！", 0, 1, 1, 0, "vo_minigame_1012_gamestart_102", 7, 3, 0, 13100103);
