INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.32, 3001, "すご、全部〇じゃん…！\nこの調子で教えてくれたら\nうちも頭よくなりそー！", 10, 2, 6, 0, "vo_minigame_1012_result_2000", 0, 1, 10, 21300101);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 6.5, 3001, "え、〇しかなかった…？\n満点ってほんとにあるんだ…\nヒデサイマジすごい…！", 10, 2, 6, 3, "vo_minigame_1012_result_2001", 2, 1, 10, 21300102);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.1, 3001, "満点じゃん！　やりー！\nもしかしてヒデサイには\n簡単過ぎた感じ？", 10, 2, 3, 5, "vo_minigame_1012_result_2002", 6, 1, 10, 21300103);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.06, 3001, "ビシッと決まったね！\nヒデサイ、ベンキョー\n教えてくれてありがとー♪", 10, 2, 3, 11, "vo_minigame_1012_result_2003", 2, 1, 10, 21300104);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.45, 3001, "ムズい問題もぜーんぶ正解！\n激アツじゃん！\nヒデサイ、頭よすぎ～", 10, 2, 3, 0, "vo_minigame_1012_result_2004", 7, 1, 10, 21300105);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.01, 3001, "きゃはっ、満点じゃん！\n一緒にベンキョーしてる\nうちまでいい気分！", 10, 2, 2, 11, "vo_minigame_1012_result_2005", 2, 1, 10, 21300106);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 6.64, 3001, "ヒデサイ、満点パーフェクト！\nこれで、もーサイツヨだね！\nそれっ、ハイタッチ～！", 10, 2, 2, 11, "vo_minigame_1012_result_2006", 3, 1, 10, 21300107);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "カンペキ過ぎて\nまぶしぃんですけど！\n〇しかないってどゆこと！？", 10, 2, 6, 0, "vo_minigame_1012_result_2007", 6, 1, 10, 21300108);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.76, 3001, "おにムズでも満点じゃん…！\nヒデサイセンセーマジすごい！\nこれからも頼りにしてるよ～", 10, 2, 6, 0, "vo_minigame_1012_result_2008", 7, 1, 10, 21300109);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "ヒデサイ、もしかして\nよゆーな感じ？\n正解しまくりじゃん！", 7, 2, 6, 0, "vo_minigame_1012_result_2009", 6, 1, 9, 21300110);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.59, 3001, "〇いっぱいで、わろ～\nてかヒデサイ教えるのうまっ！\nめちゃわかりやすかったよ♪", 7, 2, 2, 0, "vo_minigame_1012_result_2010", 7, 1, 9, 21300111);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.09, 3001, "これだけ〇あったら、\nめちゃ気持ちいいね♪\n次は満点取っちゃおー！", 7, 2, 2, 11, "vo_minigame_1012_result_2011", 3, 1, 9, 21300112);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.47, 3001, "満点まで、もーすぐじゃん！\nさっすがヒデサイ！\nバイブス上がってきた～", 7, 2, 2, 0, "vo_minigame_1012_result_2012", 3, 1, 9, 21300113);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.01, 3001, "きゃはっ、めちゃ解けてる～\nもー次は満点っしょ！\nテンアゲしてきたね♪", 7, 2, 3, 11, "vo_minigame_1012_result_2013", 3, 1, 9, 21300114);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "ヒデサイのおかげで\nうちもちょっちベンキョー\nわかってきたかも！", 7, 2, 2, 0, "vo_minigame_1012_result_2014", 2, 1, 9, 21300115);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.45, 3001, "おにムズ問題も\n〇ばっかじゃん…！\nヒデサイ、マジ心強い！", 7, 2, 6, 0, "vo_minigame_1012_result_2015", 2, 1, 9, 21300116);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "ヒデサイセンセーに\n追いつけ追い越せ！\nうちもがんばる～！", 7, 2, 3, 0, "vo_minigame_1012_result_2016", 3, 1, 9, 21300117);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.0, 3001, "おにムズ問題も\nあとちょいで満点じゃん！\nもーここまできたら\nやるしかないっしょ！", 7, 2, 2, 0, "vo_minigame_1012_result_2017", 3, 1, 9, 21300118);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.92, 3001, "お！　あと半分だし\nうちも、もうちっと\nがんばってみるね！", 4, 2, 6, 0, "vo_minigame_1012_result_2018", 0, 1, 6, 21300119);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.36, 3001, "まだイミフな問題あるけど\n悪くないよね？\nバイブス上がってきたし\n次もっとイケんじゃない？", 4, 2, 0, 0, "vo_minigame_1012_result_2019", 3, 1, 6, 21300120);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.35, 3001, "だいたい半分ぐらい？\nじゃあ、こっからだね！\n集中、集中！", 4, 2, 6, 0, "vo_minigame_1012_result_2020", 2, 1, 6, 21300121);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.13, 3001, "これで半分ぐらい？\nよしっ、とりま赤点回避！\nやりー！", 4, 2, 0, 0, "vo_minigame_1012_result_2021", 2, 1, 6, 21300122);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.38, 3001, "あともう半分だね！\nフレッフレッ、ヒデサイ！\nうちもがんばる～！", 4, 2, 0, 0, "vo_minigame_1012_result_2022", 2, 1, 6, 21300123);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3.5, 3001, "う～ん、やっぱムズいね\nでも、半分ぐらい〇だし\nイケそーな気するね！", 4, 2, 4, 0, "vo_minigame_1012_result_2023", 0, 1, 6, 21300124);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.25, 3001, "だいたい半分正解？\nとゆーことは\nあと半分で満点じゃん！", 4, 2, 0, 0, "vo_minigame_1012_result_2024", 6, 1, 6, 21300125);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.14, 3001, "やるじゃんヒデサイ！\nえ？　もっと上目指すの？\nじゃあうちもがんばる！", 4, 2, 3, 0, "vo_minigame_1012_result_2025", 6, 1, 6, 21300126);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.75, 3001, "おにムズだったのに\n半分解けてる…！？\nヒデサイいい感じ！", 4, 2, 6, 0, "vo_minigame_1012_result_2026", 2, 1, 6, 21300127);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.53, 3001, "おにムズだったね～\n…え？　これって簡単なの？\nえへへ、うそだ～？", 1, 2, 4, 5, "vo_minigame_1012_result_2027", 10, 1, 3, 21300128);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "…ねーねー、ヒデサイ\nうちに合わせて\n悪い点取らなくていいんだよ？", 1, 2, 4, 9, "vo_minigame_1012_result_2028", 4, 1, 3, 21300129);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.93, 3001, "ウォーミングアップは\nこんなところで…\nヒデサイ、次は\n本気出しちゃおうよ！", 1, 2, 0, 0, "vo_minigame_1012_result_2029", 3, 1, 3, 21300130);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.26, 3001, "あ、ヒデサイ\nうちと点数おそろじゃん！\n一緒に赤点取っちゃおっか～♪", 1, 2, 0, 4, "vo_minigame_1012_result_2030", 3, 1, 3, 21300131);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "えーっと…\nもっかい教えてくれたら\n次はもうちょい\nイケる気するよっ！", 1, 2, 10, 0, "vo_minigame_1012_result_2031", 10, 1, 3, 21300132);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.98, 3001, "うちもさっぱりだった～\nどこ間違えたんだろ…？\nもっかいベンキョーしてみる？", 1, 2, 9, 5, "vo_minigame_1012_result_2032", 0, 1, 3, 21300133);
