INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.51, 3001, "やっぱムズいね…\nでも０点じゃないし\nオーライっしょ！", 1, 2, 4, 11, "vo_minigame_1012_result_2035", 10, 1, 3, 21300136);
