INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.81, 3001, "〇多すぎてわろ～\nスラスラ解いてくし\nまじカッコよかったよ♪", 20, 2, 2, 4, "vo_minigame_1012_result_2045", 3, 2, -1, 22300101);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.31, 3001, "点数イケイケじゃん！　\nもしかして、ヒデサイには\n簡単過ぎた感じ？", 20, 2, 3, 11, "vo_minigame_1012_result_2046", 2, 2, -1, 22300102);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "きゃはっ、もうバッチリだね♪\n他の問題も教えてほしーし\n次はムズいのいっちゃう？", 20, 2, 3, 11, "vo_minigame_1012_result_2047", 3, 2, -1, 22300103);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.33, 3001, "ムズい問題なのに\n〇でいっぱいじゃん…！\nさっすが、ヒデサイセンセー！", 20, 2, 6, 11, "vo_minigame_1012_result_2048", 7, 2, -1, 22300104);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.73, 3001, "一緒にベンキョー\nしてるだけなのに\nうちまで賢くなった気する…！\nマジありがとね", 20, 2, 6, 0, "vo_minigame_1012_result_2049", 2, 2, -1, 22300105);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.01, 3001, "これってムズい問題だよね？\nなんで簡単に解いてくの？\nヒデサイ、すごすぎ！", 20, 2, 6, 8, "vo_minigame_1012_result_2050", 6, 2, -1, 22300106);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.02, 3001, "おにムズなのに\n答えるの一瞬だったね…！\nヒデサイ、頭良すぎじゃん？", 20, 2, 6, 0, "vo_minigame_1012_result_2051", 3, 2, -1, 22300107);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.24, 3001, "まる、まる、はなまる～\nきゃははっ、すごっ！\nさっすがヒデサイ！\nハイタッチー！", 20, 2, 2, 11, "vo_minigame_1012_result_2052", 3, 2, -1, 22300108);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.6, 3001, "これだけ教えてもらったら\nもうテストもよゆーっしょ！\nヒデサイ、マジありがとね♪", 20, 2, 2, 4, "vo_minigame_1012_result_2053", 3, 2, -1, 22300109);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 5.57, 3001, "うちこんなの初めて見た…！\nヒデサイセンセー、神ってる！\nそだ、記念にこれ飾っとこうよ♪\nえ、それはちょっち恥ずかしい？", 20, 2, 6, 0, "vo_minigame_1012_result_2054", 10, 2, -1, 22300110);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.57, 3001, "うちこんなの初めて見た…！\nヒデサイセンセー、神ってる！\nそだ、記念にこれ飾っとこうよ♪\nえ、それはちょっち恥ずかしい？", 20, 2, 6, 0, "vo_minigame_1012_result_2054", 10, 2, -1, 22300112);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.57, 3001, "うちこんなの初めて見た…！\nヒデサイセンセー、神ってる！\nそだ、記念にこれ飾っとこうよ♪\nえ、それはちょっち恥ずかしい？", 20, 2, 6, 0, "vo_minigame_1012_result_2054", 10, 2, -1, 22300114);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "めちゃ問題あったのに\nバンバン答えてくし\n超頼もしかった！", 15, 2, 2, 0, "vo_minigame_1012_result_2056", 2, 2, 19, 22300116);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 5.23, 3001, "おーさすがヒデサイ！\n〇の数も超ヒデサイだね♪\nイェーイ！", 15, 2, 6, 11, "vo_minigame_1012_result_2057", 3, 2, 19, 22300117);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3.23, 3001, "ヒデサイ、〇でいっぱいじゃん♪\nうちも教えてもらったとこは\nけっこー覚えてきたかも？", 15, 2, 3, 11, "vo_minigame_1012_result_2058", 2, 2, 19, 22300118);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 6.0, 3001, "アゲアゲな点数じゃん！\nとりま、どやっとく？\nせーの、どやぁ…！", 15, 2, 3, 10, "vo_minigame_1012_result_2059", 7, 2, 19, 22300119);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "ムズい問題も\nだんだん解けてくると\nたのしーね\nちょっち感動～", 15, 2, 7, 0, "vo_minigame_1012_result_2060", 7, 2, 19, 22300120);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "たくさん解いても\nヒデサイは頭パンクしないの？\nスゴ…！", 15, 2, 6, 0, "vo_minigame_1012_result_2061", 6, 2, 19, 22300121);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.06, 3001, "わわっ、〇ばっかり…！\nこの調子なら\n次は20に届くんじゃない？", 15, 2, 6, 3, "vo_minigame_1012_result_2062", 2, 2, 19, 22300122);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 5.74, 3001, "15個以上〇って…！\nおにムズなのに、すごすぎ～\nうちもがんばらなきゃ！", 15, 2, 6, 0, "vo_minigame_1012_result_2063", 5, 2, 19, 22300123);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.67, 3001, "すっごい集中力…！\nもしかして、ヒデサイ\nおにムズ問題ほど\n燃える感じっしょ？", 15, 2, 6, 0, "vo_minigame_1012_result_2064", 3, 2, 19, 22300124);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "きゃはっ、いい感じ！\nたくさん解けてるし\nベンキョーの成果\n…ってやつだね♪", 10, 2, 3, 0, "vo_minigame_1012_result_2067", 3, 2, 14, 22300131);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "10個以上〇だね♪\nヒデサイのおかげで\nうちも、ちょっち\n頭よくなったかな？", 10, 2, 2, 0, "vo_minigame_1012_result_2068", 2, 2, 14, 22300132);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.28, 3001, "けっこー解けたよね？\nやっぱ〇増えると\nバイブス上がる～", 10, 2, 10, 0, "vo_minigame_1012_result_2069", 2, 2, 14, 22300133);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "ベンキョーってあれだね\nわかった気すると\nまあまあたのしーかも！", 10, 2, 2, 0, "vo_minigame_1012_result_2070", 2, 2, 14, 22300134);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.1, 3001, "10個以上解けてる！？\nけっこーいいペースだよね？\nいい調子、いい調子～", 10, 2, 6, 0, "vo_minigame_1012_result_2071", 2, 2, 14, 22300135);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.13, 3001, "けっこー解けてる！\nムズい問題もヒデサイと\n一緒なら怖くないね♪", 10, 2, 2, 0, "vo_minigame_1012_result_2072", 3, 2, 14, 22300136);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "おにムズ問題でも教えるの\n超やさしーし、マジ感謝！\n一緒にがんばろーね♪", 10, 2, 7, 0, "vo_minigame_1012_result_2073", 7, 2, 14, 22300137);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 0.0, 3001, "おにムズなのに\n〇けっこーあるし\nヒデサイすごくない？", 10, 2, 6, 0, "vo_minigame_1012_result_2074", 6, 2, 14, 22300138);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.21, 3001, "おにムズでこのペースは\nすごいんじゃ…？\nうちもがんばってついてくね！", 10, 2, 6, 0, "vo_minigame_1012_result_2075", 5, 2, 14, 22300139);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1.94, 3001, "悪くないよね？\nでもでも\nヒデサイとうちなら\nもっとできる気する！", 5, 2, 0, 0, "vo_minigame_1012_result_2078", 3, 2, 9, 22300146);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.28, 3001, "もっと〇ほしーね…\n地道にやるしか\nないっぽいし\nもっかい教えてくれる？", 5, 2, 4, 0, "vo_minigame_1012_result_2079", 0, 2, 9, 22300147);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "ベンキョーしたけど\nわかんないとこばっか…\nヒデサイセンセー、助けて～", 5, 2, 4, 0, "vo_minigame_1012_result_2080", 4, 2, 9, 22300148);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.67, 3001, "やっぱムズかったね…\nでも次はもうちょい\nできそーな気がするよ！", 5, 2, 4, 0, "vo_minigame_1012_result_2081", 3, 2, 9, 22300149);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.68, 3001, "問題ムズいし、この点数は\nありよりのありっしょ？\nえ、もっとできた感じ？", 5, 2, 10, 0, "vo_minigame_1012_result_2082", 6, 2, 9, 22300150);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 0.0, 3001, "どこ間違ったんだろ？\nうちさっぱりだった…\nやっぱムズいだけあるね", 5, 2, 9, 0, "vo_minigame_1012_result_2083", 9, 2, 9, 22300151);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.55, 3001, "激ムズだけど\nやることは一緒だよね？\nうちもヒデサイについてくから\nコツコツがんばろ！", 5, 2, 0, 0, "vo_minigame_1012_result_2084", 3, 2, 9, 22300152);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.51, 3001, "やっぱおにムズだね…\nそだ、迷ったら\nヒント使うのも\nありよりのあり？", 5, 2, 4, 0, "vo_minigame_1012_result_2085", 6, 2, 9, 22300153);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 6.15, 3001, "やっぱテストって\nなんとなくじゃ無理？\n覚えるしかないの？\nじゃあがんばるしかないね…", 5, 2, 9, 0, "vo_minigame_1012_result_2086", 5, 2, 9, 22300154);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 4.12, 3001, "できたと思ったけど\nそーじゃなかった系？\nテストってマジきびしー…", 1, 2, 4, 6, "vo_minigame_1012_result_2087", 9, 2, 4, 22300155);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "うーん…さっぱり！\nでも簡単な問題なんだよね…？\nもっかいやってみる？", 1, 2, 4, 6, "vo_minigame_1012_result_2088", 4, 2, 4, 22300156);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 5.28, 3001, "うちらまだまだ\nベンキョーちうだし…\nこれからだよねっ？\nね、ヒデサイ！", 1, 2, 0, 0, "vo_minigame_1012_result_2089", 3, 2, 4, 22300157);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.89, 3001, "ちょっとずつ覚えれば\nおーけーっしょ！\nうちと一緒に\nベンキョーだね！", 1, 2, 0, 0, "vo_minigame_1012_result_2090", 3, 2, 4, 22300158);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 5.45, 3001, "うちベンキョー苦手でも\nヒデサイとベンキョー\nするのは好き！　だから\nもっかい教えてくれる？", 1, 2, 0, 0, "vo_minigame_1012_result_2091", 7, 2, 4, 22300159);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 4.29, 3001, "覚えても、すぐ忘れるんだけど\nどしたらいい？\nあ、そーゆうとき\nフクシューする感じ？", 1, 2, 4, 3, "vo_minigame_1012_result_2092", 10, 2, 4, 22300160);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 4.64, 3001, "ムズ過ぎ！\n頭パンクするかと思った…！\nヒデサイ、うちの頭\nふぅふぅして～", 1, 2, 4, 6, "vo_minigame_1012_result_2093", 8, 2, 4, 22300161);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 3.14, 3001, "おにムズ過ぎてテンサゲ～\nでもヒデサイがんばってるし\nうちもがんばる！", 1, 2, 9, 0, "vo_minigame_1012_result_2094", 5, 2, 4, 22300162);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 6.59, 3001, "ヒデサイと同じ点数で\nちょっち安心したかも\n一緒にがんばろーね！\n置いてっちゃやだよ？", 1, 2, 7, 0, "vo_minigame_1012_result_2095", 4, 2, 4, 22300163);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.0, 3001, "…まあ、これより下はないし\n次は大逆転\n点数爆上がりっしょ！", 0, 2, 3, 0, "vo_minigame_1012_result_2096", 3, 2, 0, 22300164);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 2.2, 3001, "０点じゃん…\nそだ、次はえんぴつ転がして\n選ぶ作戦やってみる？", 0, 2, 9, 5, "vo_minigame_1012_result_2097", 10, 2, 0, 22300165);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 0.01, 3001, "考えるの無理な時あるよね…\nヒデサイもそーゆう\n感じだったの？", 0, 2, 4, 6, "vo_minigame_1012_result_2098", 4, 2, 0, 22300166);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.8, 3001, "え、ヒデサイも０点？\nじゃあうちと一緒じゃん♪\nまあ焦んないで\nベンキョーしてこーよ！", 0, 2, 6, 3, "vo_minigame_1012_result_2099", 2, 2, 0, 22300167);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3.22, 3001, "むむむ～…０点…！\n覚えてもすぐ忘れちゃうし\nベンキョーってマジ大変", 0, 2, 9, 6, "vo_minigame_1012_result_2100", 4, 2, 0, 22300168);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 2.1, 3001, "０点だね…\nでも、へーきへーき\nリベンジしたら、結果オーライ！", 0, 2, 4, 11, "vo_minigame_1012_result_2101", 0, 2, 0, 22300169);
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (3, 2.74, 3001, "おやつ休憩して\nリベンジしよっ！\n甘いの食べたら、イケるっしょ！", 0, 2, 0, 3, "vo_minigame_1012_result_2102", 2, 2, 0, 22300170);
